    ox, oy = observation["opponent_position"]
    res = observation.get("resources", []) or []
    obst = observation.get("obstacles", []) or []
    obstacles = set((x, y) for x, y in obst)
    w = observation.get("grid_width", 8)
    h = observation.get("grid_height", 8)

    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    def step_dist(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    moves = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            nx, ny = sx + dx, sy + dy
            if inb(nx, ny) and (nx, ny) not in obstacles:
                moves.append((dx, dy))
    moves.append((0, 0))

    if not res:
        # No immediate resources: head toward the opponent to contest/deny time.
        best = (0, None)
        for dx, dy in moves:
            nx, ny = sx + dx, sy + dy
            v = -step_dist(nx, ny, ox, oy)
            if v > best[0] or (v == best[0] and (dx, dy) < best[1]):
                best = (v, (dx, dy))
        return [best[1][0], best[1][1]]

    remaining = observation.get("remaining_resource_count", len(res))
    # One-step lookahead: choose move that maximizes how much closer we become to the best attainable resource.
    best_score = -10**9
    best_move = (0, 0)
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        # If we step into resource cell, it's usually winning; make that dominant.
        on_resource = 1 if (nx, ny) in set((r[0], r[1]) for r in res) else 0
        # Evaluate best resource from this next position.
        max_v = -10**9
        for rx, ry in res:
            sd = step_dist(nx, ny, rx, ry)
            od = step_dist(ox, oy, rx, ry)
            # Prefer resources where we are earlier (od - sd positive); also prefer shorter absolute self distance.
            v = (od - sd) * 10 - sd + (2 if od > sd else 0) - (1 if od == sd else 0)
            # Slightly bias toward nearer wins when few resources remain.
            v += 0.02 * (remaining - sd)
            if v > max_v:
                max_v = v
        score = max_v + (1000 if on_resource else 0)
        # Deterministic tie-break: prefer smaller abs move, then lexicographic.
        tie = (abs(dx) + abs(dy), dx, dy)
        if score > best_score or (score == best_score and tie < (abs(best_move[0]) + abs(best_move[1]), best_move[0], best_move[1])):
            best_score = score
            best_move = (dx, dy)

    return [int(best_move[0]), int(best_move[1])]

